  for l in step['layers']:
   row={'source_seconds':step['source_seconds'],'end_seconds':step['end_seconds'],'k':l['k'],'dry_theta_change_K':l['dry_theta_change_K'],'qv_change_g_kg':1000*l['qv_change_kg_kg'],'T_change_diagnostic_K':l['T_change_diagnostic_K'],'T_theta_part_K':l['T_theta_part_K'],'T_pressure_part_K':l['T_pressure_part_K'],'dry_theta_identity_residual_K':l['dry_theta_identity_residual_K'],'qv_identity_residual_g_kg':1000*l['qv_identity_residual_kg_kg']}
