 O=B/'udm37-sterling-thermodynamic-analysis-v1';a=json.loads((O/'analysis.json').read_text());ex=json.loads((O/'extracted.json').read_text());old=json.loads((P.parent/'sterling-low-level-evolution/result.json').read_text());result=summarize(a,ex,old);(P/'result.json').write_text(json.dumps(result,indent=2)+'\n')
